import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';

const History = () => {
  const [history, setHistory] = useState([]);

  useEffect(() => {
    const savedHistory = JSON.parse(localStorage.getItem('docxHistory') || '[]');
    setHistory(savedHistory);
  }, []);

  const clearHistory = () => {
    localStorage.removeItem('docxHistory');
    setHistory([]);
  };

  const deleteHistoryItem = (id) => {
    const updatedHistory = history.filter(item => item.id !== id);
    localStorage.setItem('docxHistory', JSON.stringify(updatedHistory));
    setHistory(updatedHistory);
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleString();
  };

  return (
    <div className="min-h-screen bg-gray-100 p-4 sm:p-8 font-inter">
      <header className="text-center mb-10">
        <h1 className="text-4xl font-extrabold text-indigo-700">
          <svg className="inline-block w-8 h-8 mr-2 -mt-1" fill="currentColor" viewBox="0 0 20 20">
            <path d="M4 3a2 2 0 00-2 2v10a2 2 0 002 2h12a2 2 0 002-2V5a2 2 0 00-2-2H4zm12 12H4l4-8 3 6 2-4 3 6z"/>
          </svg>
          Processing History
        </h1>
        <p className="text-gray-500 mt-2">View your recent DOCX processing history and statistics.</p>
      </header>

      <main className="max-w-4xl mx-auto">
        {/* Actions Bar */}
        <div className="bg-white p-6 rounded-xl shadow-2xl mb-8 flex justify-between items-center">
          <div className="flex items-center space-x-4">
            <span className="text-lg font-semibold text-gray-700">
              Total Files Processed: <span className="text-indigo-600">{history.length}</span>
            </span>
          </div>
          
          {history.length > 0 && (
            <button
              onClick={clearHistory}
              className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md shadow-sm text-white bg-red-500 hover:bg-red-600 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-500 transition duration-150"
            >
              <svg className="w-4 h-4 mr-2" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M9 2a1 1 0 000 2h2a1 1 0 100-2H9z" clipRule="evenodd"/>
                <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8 7a1 1 0 012 0v4a1 1 0 11-2 0V7zM12 7a1 1 0 012 0v4a1 1 0 11-2 0V7z" clipRule="evenodd"/>
              </svg>
              Clear All History
            </button>
          )}
        </div>

        {/* History List */}
        {history.length === 0 ? (
          <div className="bg-white p-8 rounded-xl shadow-lg text-center">
            <svg className="mx-auto h-16 w-16 text-gray-400 mb-4" fill="currentColor" viewBox="0 0 20 20">
              <path d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/>
            </svg>
            <h3 className="text-lg font-medium text-gray-900 mb-2">No History Yet</h3>
            <p className="text-gray-500 mb-4">Start processing DOCX files to see your history here.</p>
            <Link 
              to="/" 
              className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md shadow-sm text-white bg-indigo-600 hover:bg-indigo-700"
            >
              Process Your First File
            </Link>
          </div>
        ) : (
          <div className="bg-white rounded-xl shadow-lg overflow-hidden">
            <div className="px-6 py-4 bg-gray-50 border-b border-gray-200">
              <h2 className="text-xl font-semibold text-gray-800">Recent Processing History</h2>
            </div>
            
            <div className="divide-y divide-gray-200">
              {history.map((item) => (
                <div key={item.id} className="p-6 hover:bg-gray-50 transition duration-150">
                  <div className="flex items-center justify-between">
                    <div className="flex-1">
                      <div className="flex items-center space-x-3">
                        <div className="flex-shrink-0">
                          <svg className="h-8 w-8 text-indigo-500" fill="currentColor" viewBox="0 0 20 20">
                            <path d="M4 3a2 2 0 00-2 2v10a2 2 0 002 2h12a2 2 0 002-2V5a2 2 0 00-2-2H4zm0 2h12v10H4V5z"/>
                          </svg>
                        </div>
                        <div className="flex-1 min-w-0">
                          <h3 className="text-lg font-medium text-gray-900 truncate">
                            {item.fileName}
                          </h3>
                          <div className="flex items-center space-x-4 mt-1">
                            <p className="text-sm text-gray-500">
                              Processed: {formatDate(item.date)}
                            </p>
                            <p className="text-sm text-gray-500">
                              Extracted {item.dataCount} elements
                            </p>
                          </div>
                        </div>
                      </div>
                    </div>
                    
                    <div className="flex items-center space-x-2">
                      <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-800">
                        Completed
                      </span>
                      <button
                        onClick={() => deleteHistoryItem(item.id)}
                        className="text-red-400 hover:text-red-600 transition duration-150"
                        title="Delete this entry"
                      >
                        <svg className="h-5 w-5" fill="currentColor" viewBox="0 0 20 20">
                          <path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd"/>
                        </svg>
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Statistics Card */}
        {history.length > 0 && (
          <div className="mt-8 bg-white rounded-xl shadow-lg p-6">
            <h3 className="text-lg font-semibold text-gray-800 mb-4">Statistics</h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="bg-indigo-50 rounded-lg p-4">
                <h4 className="text-sm font-medium text-indigo-600">Total Files</h4>
                <p className="text-2xl font-bold text-indigo-700">{history.length}</p>
              </div>
              <div className="bg-green-50 rounded-lg p-4">
                <h4 className="text-sm font-medium text-green-600">Total Elements</h4>
                <p className="text-2xl font-bold text-green-700">
                  {history.reduce((sum, item) => sum + item.dataCount, 0)}
                </p>
              </div>
              <div className="bg-blue-50 rounded-lg p-4">
                <h4 className="text-sm font-medium text-blue-600">Avg Elements/File</h4>
                <p className="text-2xl font-bold text-blue-700">
                  {Math.round(history.reduce((sum, item) => sum + item.dataCount, 0) / history.length)}
                </p>
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default History;